/* ============================================
   LearnForge Corporate Website Styles
   Brand: #000000 (black), #E6FF32 (lime), #7F2A23 (burgundy)
   ============================================ */

/* CSS Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-primary: #000000;
  --color-accent: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-white: #FFFFFF;
  --color-gray-50: #FAFAFA;
  --color-gray-100: #F5F5F5;
  --color-gray-200: #E5E5E5;
  --color-gray-300: #D4D4D4;
  --color-gray-400: #A3A3A3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;
  --color-indigo: #4F46E5;
  --color-coral: #F97066;
  --color-green: #22C55E;

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-display: 'Plus Jakarta Sans', var(--font-sans);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 60px rgba(0,0,0,0.16);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-gray-900);
  background: var(--color-white);
  line-height: 1.6;
  overflow-x: hidden;
}

img, svg {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--color-primary);
}

.text-display {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: -0.03em;
}

.text-body {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-gray-600);
}

.text-small {
  font-size: 0.875rem;
  line-height: 1.5;
  color: var(--color-gray-500);
}

/* Layout Utilities */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

@media (min-width: 768px) {
  .container {
    padding: 0 2rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 3rem;
  }
}

.section {
  padding: 5rem 0;
}

@media (min-width: 768px) {
  .section {
    padding: 7rem 0;
  }
}

.section-title {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  max-width: 600px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-accent:hover {
  filter: brightness(0.95);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 1.5px solid var(--color-gray-300);
}

.btn-outline:hover {
  border-color: var(--color-primary);
  background: var(--color-gray-50);
}

.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-white:hover {
  background: var(--color-gray-100);
  transform: translateY(-1px);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1rem;
}

/* Cards */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
  padding: 1.5rem;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--color-gray-300);
}

.card-flat {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 2rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base);
}

.nav-scrolled {
  box-shadow: var(--shadow-sm);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 2rem;
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-primary);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-accent);
  border-radius: 1px;
}

.nav-cta {
  display: none;
}

.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 1px;
  transition: all var(--transition-base);
}

.nav-mobile-menu {
  display: none;
  position: absolute;
  top: 68px;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  padding: 1.5rem;
  flex-direction: column;
  gap: 1rem;
  box-shadow: var(--shadow-lg);
}

.nav-mobile-menu.open {
  display: flex;
}

@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }
  .nav-cta {
    display: inline-flex;
  }
  .nav-mobile-toggle {
    display: none;
  }
}

/* Hero */
.hero {
  padding-top: 120px;
  padding-bottom: 5rem;
  position: relative;
  overflow: hidden;
}

.hero-inner {
  display: grid;
  gap: 3rem;
  align-items: center;
}

@media (min-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr 1.1fr;
    gap: 4rem;
  }
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  line-height: 1.1;
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  margin-bottom: 2rem;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.hero-tabs {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  gap: 4px;
}

.hero-tab {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--color-gray-500);
  transition: all var(--transition-base);
}

.hero-tab:hover {
  color: var(--color-primary);
}

.hero-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.hero-visual {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  background: var(--color-gray-100);
}

.hero-visual img {
  width: 100%;
  display: block;
  transition: opacity var(--transition-base);
}

.hero-visual-tab {
  display: none;
}

.hero-visual-tab.active {
  display: block;
}

/* Stats Bar */
.stats-bar {
  background: var(--color-primary);
  color: var(--color-white);
  padding: 3rem 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 2rem;
  text-align: center;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-number {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-accent);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
}

/* Products Grid */
.products-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
}

@media (min-width: 640px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}

.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--color-gray-300);
}

.product-icon {
  width: 48px;
  height: 48px;
  margin-bottom: 1.25rem;
}

.product-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.product-desc {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* Why Choose Us Tabs */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 2.5rem;
  margin-bottom: 2rem;
}

.why-tab {
  padding: 0.75rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--color-gray-500);
  background: var(--color-gray-100);
  transition: all var(--transition-base);
  border: 2px solid transparent;
}

.why-tab:hover {
  color: var(--color-primary);
  background: var(--color-gray-200);
}

.why-tab.active {
  color: var(--color-primary);
  background: var(--color-accent);
  border-color: var(--color-primary);
}

.why-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.why-panel.active {
  display: block;
}

.why-features {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 1rem;
}

@media (min-width: 640px) {
  .why-features {
    grid-template-columns: repeat(2, 1fr);
  }
}

.why-feature {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
}

.why-feature-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.why-feature-icon svg {
  width: 18px;
  height: 18px;
}

.why-feature-text h4 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.why-feature-text p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

/* Testimonials Carousel */
.testimonials-section {
  background: var(--color-gray-50);
}

.testimonials-carousel {
  position: relative;
  margin-top: 3rem;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 0.5rem;
}

@media (min-width: 768px) {
  .testimonial-card {
    flex: 0 0 50%;
  }
}

@media (min-width: 1024px) {
  .testimonial-card {
    flex: 0 0 33.333%;
  }
}

.testimonial-inner {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--color-gray-200);
  height: 100%;
}

.testimonial-quote {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--color-gray-700);
  margin-bottom: 1.5rem;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.testimonial-avatar {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  object-fit: cover;
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.9375rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.testimonial-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-burgundy);
  background: rgba(127,42,35,0.08);
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.75rem;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-base);
}

.carousel-btn:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: var(--color-white);
}

.carousel-btn svg {
  width: 18px;
  height: 18px;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--color-gray-300);
  transition: all var(--transition-base);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 24px;
}

/* Pricing */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
}

@media (min-width: 768px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .pricing-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.pricing-card.featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.375rem 1rem;
  border-radius: var(--radius-full);
}

.pricing-name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.pricing-price {
  font-family: var(--font-display);
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 0.25rem;
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
}

.pricing-features {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  font-size: 0.875rem;
  color: var(--color-gray-600);
}

.pricing-feature svg {
  width: 18px;
  height: 18px;
  color: var(--color-green);
  flex-shrink: 0;
}

/* Integrations */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-top: 3rem;
}

@media (min-width: 640px) {
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .integrations-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
}

.integration-item:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  border-color: var(--color-gray-300);
}

.integration-item img {
  max-height: 28px;
  width: auto;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 3rem auto 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition-base);
}

.faq-item:hover {
  border-color: var(--color-gray-300);
}

.faq-item.active {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--color-primary);
}

.faq-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
  flex-shrink: 0;
  margin-left: 1rem;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-slow);
}

.faq-item.active .faq-answer {
  max-height: 300px;
  padding: 0 1.5rem 1.25rem;
}

.faq-answer p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.7;
}

/* CTA Banner */
.cta-banner {
  background: var(--color-primary);
  color: var(--color-white);
  padding: 5rem 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner .section-title {
  color: var(--color-white);
  margin-bottom: 1rem;
}

.cta-banner .section-subtitle {
  color: var(--color-gray-400);
  margin: 0 auto 2rem;
}

/* Footer */
.footer {
  background: var(--color-gray-900);
  color: var(--color-gray-400);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.footer-col h4 {
  color: var(--color-white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-col a {
  font-size: 0.9375rem;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid var(--color-gray-800);
  padding-top: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.footer-logo img {
  height: 28px;
}

/* Feature Sections */
.features-grid-2 {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

@media (min-width: 768px) {
  .features-grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

.features-grid-3 {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

@media (min-width: 768px) {
  .features-grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

.feature-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}

.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.feature-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.75rem;
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

.feature-icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
}

.feature-icon-wrap svg {
  width: 24px;
  height: 24px;
}

/* Steps */
.steps {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  margin-top: 3rem;
}

@media (min-width: 768px) {
  .steps {
    flex-direction: row;
  }
}

.step {
  flex: 1;
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-full);
  background: var(--color-accent);
  color: var(--color-primary);
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.step p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.6;
}

/* Spotlight Cards */
.spotlight-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}

.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.spotlight-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.spotlight-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.7;
}

/* Resources */
.resource-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all var(--transition-base);
}

.resource-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-primary);
}

.resource-card h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.resource-card p {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

/* Product Demo Accordion */
.demo-accordion {
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-top: 2rem;
}

.demo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 1.5rem;
  background: var(--color-gray-50);
  font-size: 1rem;
  font-weight: 600;
}

.demo-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
}

.demo-accordion.open .demo-header svg {
  transform: rotate(180deg);
}

.demo-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.demo-accordion.open .demo-content {
  max-height: 600px;
}

.demo-inner {
  padding: 1.5rem;
}

/* Tools Grid */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-top: 3rem;
}

@media (min-width: 640px) {
  .tools-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .tools-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

.tool-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.tool-item:hover {
  border-color: var(--color-primary);
  background: var(--color-gray-50);
}

.tool-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-full);
  background: var(--color-accent);
}

/* File Types */
.file-types {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 2rem;
  justify-content: center;
}

.file-type {
  padding: 0.625rem 1.25rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.file-type:hover {
  background: var(--color-accent);
  border-color: var(--color-primary);
}

/* Social Proof / Trust Bar */
.trust-bar {
  background: var(--color-gray-50);
  padding: 3rem 0;
  text-align: center;
}

.trust-text {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-fade-in {
  animation: fadeIn 0.5s ease forwards;
}

.animate-slide-up {
  animation: slideInUp 0.6s ease forwards;
}

/* Scroll reveal */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Section header centering */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 1rem;
}

/* Dark section variant */
.section-dark {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-dark h2,
.section-dark h3 {
  color: var(--color-white);
}

.section-dark .section-subtitle {
  color: var(--color-gray-400);
}

/* Light accent section */
.section-accent {
  background: var(--color-gray-50);
}

/* Grid with image */
.split-section {
  display: grid;
  gap: 3rem;
  align-items: center;
}

@media (min-width: 1024px) {
  .split-section {
    grid-template-columns: 1fr 1fr;
  }
  .split-section.reverse {
    grid-template-columns: 1fr 1fr;
    direction: rtl;
  }
  .split-section.reverse > * {
    direction: ltr;
  }
}

.split-image {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.split-image img {
  width: 100%;
}

/* Highlight text */
.highlight {
  background: linear-gradient(180deg, transparent 60%, var(--color-accent) 60%);
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.875rem;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
}

.badge-accent {
  background: var(--color-accent);
  color: var(--color-primary);
}

/* Enterprise card */
.enterprise-card {
  background: var(--color-gray-900);
  color: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  margin-top: 2rem;
}

.enterprise-card h3 {
  color: var(--color-white);
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.enterprise-card p {
  color: var(--color-gray-400);
  margin-bottom: 1.5rem;
}

.enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.enterprise-feature {
  padding: 0.5rem 1rem;
  background: rgba(255,255,255,0.08);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
}

/**
 * LearnForge Website - Main JavaScript
 * Handles navigation, carousels, tabs, accordions, and scroll animations
 */

(function() {
  'use strict';

  // ==========================================
  // Navigation
  // ==========================================
  const nav = document.querySelector('.nav');
  const mobileToggle = document.querySelector('.nav-mobile-toggle');
  const mobileMenu = document.querySelector('.nav-mobile-menu');

  if (nav) {
    window.addEventListener('scroll', function() {
      if (window.scrollY > 20) {
        nav.classList.add('nav-scrolled');
      } else {
        nav.classList.remove('nav-scrolled');
      }
    });
  }

  if (mobileToggle && mobileMenu) {
    mobileToggle.addEventListener('click', function() {
      mobileMenu.classList.toggle('open');
      const spans = mobileToggle.querySelectorAll('span');
      if (mobileMenu.classList.contains('open')) {
        spans[0].style.transform = 'rotate(45deg) translate(5px, 5px)';
        spans[1].style.opacity = '0';
        spans[2].style.transform = 'rotate(-45deg) translate(5px, -5px)';
      } else {
        spans[0].style.transform = '';
        spans[1].style.opacity = '';
        spans[2].style.transform = '';
      }
    });

    // Close mobile menu on link click
    mobileMenu.querySelectorAll('a').forEach(function(link) {
      link.addEventListener('click', function() {
        mobileMenu.classList.remove('open');
        const spans = mobileToggle.querySelectorAll('span');
        spans[0].style.transform = '';
        spans[1].style.opacity = '';
        spans[2].style.transform = '';
      });
    });
  }

  // ==========================================
  // Scroll Reveal Animation
  // ==========================================
  const revealElements = document.querySelectorAll('.reveal');

  function checkReveal() {
    const windowHeight = window.innerHeight;
    const revealPoint = 100;

    revealElements.forEach(function(el) {
      const revealTop = el.getBoundingClientRect().top;
      if (revealTop < windowHeight - revealPoint) {
        el.classList.add('visible');
      }
    });
  }

  if (revealElements.length > 0) {
    window.addEventListener('scroll', checkReveal);
    window.addEventListener('load', checkReveal);
    checkReveal();
  }

  // ==========================================
  // Hero Tab Switcher (Homepage)
  // ==========================================
  const heroTabs = document.querySelectorAll('.hero-tab');
  const heroVisualTabs = document.querySelectorAll('.hero-visual-tab');

  heroTabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      const target = tab.dataset.tab;

      heroTabs.forEach(function(t) { t.classList.remove('active'); });
      tab.classList.add('active');

      heroVisualTabs.forEach(function(vt) {
        vt.classList.toggle('active', vt.dataset.tab === target);
      });
    });
  });

  // ==========================================
  // Why Choose Us Tabs (Homepage)
  // ==========================================
  const whyTabs = document.querySelectorAll('.why-tab');
  const whyPanels = document.querySelectorAll('.why-panel');

  whyTabs.forEach(function(tab) {
    tab.addEventListener('click', function() {
      const target = tab.dataset.panel;

      whyTabs.forEach(function(t) { t.classList.remove('active'); });
      tab.classList.add('active');

      whyPanels.forEach(function(panel) {
        panel.classList.toggle('active', panel.dataset.panel === target);
      });
    });
  });

  // ==========================================
  // FAQ Accordion
  // ==========================================
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(function(item) {
    const question = item.querySelector('.faq-question');
    if (question) {
      question.addEventListener('click', function() {
        const isActive = item.classList.contains('active');

        // Close all siblings if you want accordion behavior (single open)
        const parent = item.closest('.faq-list');
        if (parent) {
          parent.querySelectorAll('.faq-item').forEach(function(sib) {
            sib.classList.remove('active');
          });
        }

        if (!isActive) {
          item.classList.add('active');
        }
      });
    }
  });

  // ==========================================
  // Product Demo Accordion (Online Courses)
  // ==========================================
  const demoAccordion = document.querySelector('.demo-accordion');
  if (demoAccordion) {
    const demoHeader = demoAccordion.querySelector('.demo-header');
    if (demoHeader) {
      demoHeader.addEventListener('click', function() {
        demoAccordion.classList.toggle('open');
      });
    }
  }

  // ==========================================
  // Testimonials Carousel
  // ==========================================
  function initCarousel(container) {
    if (!container) return;

    const track = container.querySelector('.testimonials-track');
    const cards = container.querySelectorAll('.testimonial-card');
    const prevBtn = container.querySelector('.carousel-prev');
    const nextBtn = container.querySelector('.carousel-next');
    const dotsContainer = container.querySelector('.carousel-dots');

    if (!track || cards.length === 0) return;

    let currentIndex = 0;
    let itemsPerView = 1;

    function updateItemsPerView() {
      if (window.innerWidth >= 1024) {
        itemsPerView = 3;
      } else if (window.innerWidth >= 768) {
        itemsPerView = 2;
      } else {
        itemsPerView = 1;
      }
    }

    function getMaxIndex() {
      return Math.max(0, cards.length - itemsPerView);
    }

    function updateCarousel() {
      const cardWidth = cards[0].offsetWidth;
      track.style.transform = 'translateX(' + (-currentIndex * cardWidth) + 'px)';

      // Update dots
      if (dotsContainer) {
        const dots = dotsContainer.querySelectorAll('.carousel-dot');
        dots.forEach(function(dot, i) {
          dot.classList.toggle('active', i === currentIndex);
        });
      }
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        currentIndex = Math.max(0, currentIndex - 1);
        updateCarousel();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        currentIndex = Math.min(getMaxIndex(), currentIndex + 1);
        updateCarousel();
      });
    }

    // Create dots
    if (dotsContainer) {
      const maxIndex = getMaxIndex();
      dotsContainer.innerHTML = '';
      for (let i = 0; i <= maxIndex; i++) {
        const dot = document.createElement('button');
        dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
        dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
        dot.addEventListener('click', function() {
          currentIndex = i;
          updateCarousel();
        });
        dotsContainer.appendChild(dot);
      }
    }

    window.addEventListener('resize', function() {
      updateItemsPerView();
      currentIndex = Math.min(currentIndex, getMaxIndex());
      updateCarousel();
    });

    updateItemsPerView();
    updateCarousel();

    // Auto-play
    let autoPlay = setInterval(function() {
      const maxIndex = getMaxIndex();
      if (currentIndex < maxIndex) {
        currentIndex++;
      } else {
        currentIndex = 0;
      }
      updateCarousel();
    }, 5000);

    container.addEventListener('mouseenter', function() {
      clearInterval(autoPlay);
    });

    container.addEventListener('mouseleave', function() {
      autoPlay = setInterval(function() {
        const maxIndex = getMaxIndex();
        if (currentIndex < maxIndex) {
          currentIndex++;
        } else {
          currentIndex = 0;
        }
        updateCarousel();
      }, 5000);
    });
  }

  document.querySelectorAll('.testimonials-carousel').forEach(initCarousel);

  // ==========================================
  // Smooth scroll for anchor links
  // ==========================================
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
    anchor.addEventListener('click', function(e) {
      const targetId = anchor.getAttribute('href');
      if (targetId === '#') return;
      const targetEl = document.querySelector(targetId);
      if (targetEl) {
        e.preventDefault();
        const navHeight = nav ? nav.offsetHeight : 0;
        const targetPosition = targetEl.getBoundingClientRect().top + window.pageYOffset - navHeight;
        window.scrollTo({ top: targetPosition, behavior: 'smooth' });
      }
    });
  });

})();
